def semver_sort(versions):
    def parse_version(v):
        # Split build metadata
        if '+' in v:
            v, build = v.split('+', 1)
        else:
            build = ''

        # Split pre-release
        if '-' in v:
            core, prerelease = v.split('-', 1)
        else:
            core = v
            prerelease = None

        # Parse core version
        parts = core.split('.')
        major = int(parts[0])
        minor = int(parts[1]) if len(parts) > 1 else 0
        patch = int(parts[2]) if len(parts) > 2 else 0

        # Parse pre-release identifiers
        if prerelease is not None:
            identifiers = prerelease.split('.')
            pre_parsed = []
            for ident in identifiers:
                if ident.isdigit():
                    pre_parsed.append((0, int(ident)))
                else:
                    pre_parsed.append((1, ident))
        else:
            pre_parsed = None

        return (major, minor, patch, pre_parsed)

    def compare_key(v):
        major, minor, patch, pre_parsed = parse_version(v)

        # For sorting: (major, minor, patch, has_prerelease, prerelease_tuple)
        # has_prerelease: False (0) if no prerelease, True (1) if has prerelease
        # Versions without prerelease should sort after versions with prerelease for same core

        if pre_parsed is None:
            return (major, minor, patch, 1, ())
        else:
            return (major, minor, patch, 0, tuple(pre_parsed))

    return sorted(versions, key=compare_key)

